// Watching the pasteboard and putting entries back on it.

import AppKit
import ApplicationServices
import ImageIO

/// Apps mark passwords and other short-lived content with these types (see nspasteboard.org) so that clipboard
/// tools leave it alone.
private let ignoredTypes: Set<String> = [
    "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword", "com.typeit4me.clipping", "de.petermaurer.TransientPasteboardType",
    "Pasteboard generator type", "net.antelle.keeweb",
]

private let inlineBytes = 256 * 1024  // smaller texts are saved at once, larger ones in the background
private let thumbHeight = 80.0        // pixels, 40 points on a Retina screen
private let thumbMaxWidth = 480.0
let jpegType = NSPasteboard.PasteboardType("public.jpeg")

/// Text that an app put next to a picture only to label it: a URL, a path or a file name.
private func isLabel(_ text: Data) -> Bool {
    guard !text.isEmpty, text.count <= 2048, let s = String(data: text, encoding: .utf8),
          s.rangeOfCharacter(from: .newlines) == nil
    else { return false }
    if s.contains("://") || s.hasPrefix("/") || s.hasPrefix("data:") { return true }
    return !(s as NSString).pathExtension.isEmpty && !s.contains(" ")
}

private func head(_ data: Data) -> [UInt8] {
    data.withUnsafeBytes { raw in
        let bytes = raw.bindMemory(to: UInt8.self)
        return Array(bytes[..<utf8PrefixLength(bytes, maxBytes: Store.headBytes)])
    }
}

private func write(_ path: String, _ data: Data) -> Bool {
    data.withUnsafeBytes { writeFile(path, $0) }
}

private func mapped(_ path: String) -> Data? {
    try? Data(contentsOf: URL(fileURLWithPath: path), options: .mappedIfSafe)
}

/// Reads the first item on a pasteboard through a reference of Crumb's own, let go as soon as the copy is read:
/// NSPasteboard keeps everything read through it in memory until the next copy, tens of megabytes for a screenshot.
private struct Reader {
    private var pasteboard: Pasteboard?
    private var item: PasteboardItemID?

    init(_ board: NSPasteboard) {
        // AppKit's general pasteboard is Carbon's clipboard (kPasteboardClipboard).
        let name = board.name == .general ? "com.apple.pasteboard.clipboard" : board.name.rawValue
        guard PasteboardCreate(name as CFString, &pasteboard) == noErr, let pasteboard else { return }
        PasteboardSynchronize(pasteboard)
        if PasteboardGetItemIdentifier(pasteboard, 1, &item) != noErr { item = nil }
    }

    func data(_ type: NSPasteboard.PasteboardType) -> Data? {
        guard let pasteboard, let item else { return nil }
        var data: CFData?
        guard PasteboardCopyItemFlavorData(pasteboard, item, type.rawValue as CFString, &data) == noErr else { return nil }
        return data as Data?
    }
}

/// The largest picture in a source (TIFFs often hold 1x and 2x versions) and its EXIF orientation (1 is upright).
private func largestImage(_ source: CGImageSource) -> (index: Int, width: Double, height: Double, orientation: Int) {
    var best = (index: 0, width: 0.0, height: 0.0, orientation: 1)
    for i in 0..<CGImageSourceGetCount(source) {
        guard let properties = CGImageSourceCopyPropertiesAtIndex(source, i, nil) as? [CFString: Any] else { continue }
        let w = (properties[kCGImagePropertyPixelWidth] as? NSNumber)?.doubleValue ?? 0
        let h = (properties[kCGImagePropertyPixelHeight] as? NSNumber)?.doubleValue ?? 0
        let orientation = (properties[kCGImagePropertyOrientation] as? NSNumber)?.intValue ?? 1
        if w * h > best.width * best.height { best = (i, w, h, orientation) }
    }
    return best
}

/// PNG from either a decoded picture or, straight from its source, a picture that is already upright: ImageIO then
/// never needs the whole picture decoded at once, and a screenshot converts with less than half the memory.
private func encodePNG(_ image: CGImage?, source: CGImageSource? = nil, index: Int = 0) -> Data? {
    let data = NSMutableData()
    guard let destination = CGImageDestinationCreateWithData(data, "public.png" as CFString, 1, nil) else { return nil }
    if let image {
        CGImageDestinationAddImage(destination, image, nil)
    } else if let source {
        CGImageDestinationAddImageFromSource(destination, source, index, nil)
    }
    return CGImageDestinationFinalize(destination) ? data as Data : nil
}

private func thumbnail(_ source: CGImageSource, _ index: Int, maxPixels: Double) -> CGImage? {
    let options: [CFString: Any] = [
        kCGImageSourceCreateThumbnailFromImageAlways: true,
        kCGImageSourceCreateThumbnailWithTransform: true,
        kCGImageSourceThumbnailMaxPixelSize: maxPixels,
    ]
    return CGImageSourceCreateThumbnailAtIndex(source, index, options as CFDictionary)
}

/// `width` and `height` are the picture's size as shown (after any rotation).
private func writeThumbnail(_ source: CGImageSource, _ index: Int, width: Double, height: Double, to path: String) {
    guard width >= 1, height >= 1 else { return }
    let scale = min(1, thumbHeight / height, thumbMaxWidth / width)
    if let thumb = thumbnail(source, index, maxPixels: max(1, (max(width, height) * scale).rounded(.up))),
       let png = encodePNG(thumb) {
        _ = write(path, png)
    }
}

/// Converts a stored picture to the format a pasting app asks for, only when it asks. Keeps the picture mapped, so
/// pasting still works after its entry is deleted.
private final class ImageProvider: NSObject, NSPasteboardItemDataProvider {
    private let data: Data

    init(_ data: Data) {
        self.data = data
    }

    func pasteboard(_ pasteboard: NSPasteboard?, item: NSPasteboardItem, provideDataForType type: NSPasteboard.PasteboardType) {
        autoreleasepool {
            guard let source = CGImageSourceCreateWithData(data as CFData, nil) else { return }
            let out = NSMutableData()
            let uti = type == .tiff ? "public.tiff" : "public.png"
            guard let destination = CGImageDestinationCreateWithData(out, uti as CFString, 1, nil) else { return }
            CGImageDestinationAddImageFromSource(destination, source, 0, nil)
            if CGImageDestinationFinalize(destination) { item.setData(out as Data, forType: type) }
        }
    }
}

@MainActor
final class Clipboard {
    private let store: Store
    var onChange: (() -> Void)?

    private var timer: DispatchSourceTimer?
    private let io = DispatchQueue(label: "crumb.save", qos: .utility)
    private var seen = -1       // change count already handled
    private var own = -1        // change count of Crumb's own last write
    private var noticed = -1    // a change count waiting for its app to finish writing
    private var noticedAt: CFTimeInterval = 0
    private var saving = 0      // saves still running in the background
    private var picks = 0       // entries put back on the pasteboard so far
    private var clears = 0      // times the history was cleared

    init(store: Store) {
        self.store = store
    }

    /// Copies are still being saved.
    var busy: Bool { saving > 0 }

    func start() {
        // Apps don't announce copies, so the change count is checked twice a second (a cheap call).
        let timer = DispatchSource.makeTimerSource(queue: .main)
        timer.schedule(deadline: .now(), repeating: .milliseconds(500), leeway: .milliseconds(100))
        timer.setEventHandler { [weak self] in
            MainActor.assumeIsolated { self?.poll() }
        }
        timer.resume()
        self.timer = timer
    }

    func poll() {
        pollWaiting(settle: true)
    }

    /// Looks for a new copy right away, without waiting for it to settle.
    func pollNow() {
        pollWaiting(settle: false)
    }

    // Apps copy in two steps, clearing the pasteboard and then writing to it, so a change is read once it has
    // settled for a moment, and looked at again for a while if it still reads empty.
    private func pollWaiting(settle: Bool) {
        autoreleasepool {
            let pasteboard = NSPasteboard.general
            let count = pasteboard.changeCount
            if count == seen { return }
            let now = CACurrentMediaTime()
            if count != noticed {
                noticed = count
                noticedAt = now
                if settle {
                    DispatchQueue.main.asyncAfter(deadline: .now() + .milliseconds(100)) { [weak self] in
                        MainActor.assumeIsolated { self?.poll() }
                    }
                    return
                }
            }
            if settle && now - noticedAt < 0.09 { return }
            if count != own && !capture(pasteboard) && now - noticedAt < 2 { return }
            seen = count
        }
    }

    private func changed() {
        onChange?()
    }

    /// Saves what was copied. Returns false when the pasteboard holds nothing readable (yet).
    private func capture(_ pasteboard: NSPasteboard) -> Bool {
        guard let items = pasteboard.pasteboardItems, let first = items.first else { return false }
        for item in items where item.types.contains(where: { ignoredTypes.contains($0.rawValue) }) { return true }

        // Files arrive as one file URL per pasteboard item.
        var paths: [String] = []
        for item in items {
            if let string = item.string(forType: .fileURL), let url = URL(string: string), url.isFileURL, !url.path.isEmpty {
                paths.append(url.path)
            }
        }
        if !paths.isEmpty {
            saveFiles(paths)
            return true
        }

        var text: Data?
        var rtf: Data?
        var html: Data?
        var image: Data?
        var imageType = NSPasteboard.PasteboardType.png
        do {
            let reader = Reader(pasteboard)  // let go before saving starts
            text = reader.data(.string)
            rtf = reader.data(.rtf)
            html = reader.data(.html)
            if text?.isEmpty ?? true { text = pasteboard.string(forType: .string)?.data(using: .utf8) }
            if text?.isEmpty ?? true, let rtf, !rtf.isEmpty {
                text = NSAttributedString(rtf: rtf, documentAttributes: nil)?.string.data(using: .utf8)
            }
            // A picture is kept when there is no text, or when the text only labels it (such as its URL).
            if text?.isEmpty ?? true || ((rtf?.isEmpty ?? true) && isLabel(text!)) {
                for type in [NSPasteboard.PasteboardType.png, jpegType, .tiff] where first.types.contains(type) {
                    if let data = reader.data(type), !data.isEmpty {
                        image = data
                        imageType = type
                        break
                    }
                }
            }
        }

        if let image {
            saveImage(image, type: imageType, label: text)
        } else if let text, !text.isEmpty {
            saveText(text, rtf: rtf, html: html)
        } else {
            return !first.types.isEmpty  // something Crumb doesn't keep (or not written yet)
        }
        return true
    }

    /// Copying something Crumb already has just moves that entry to the top. Returns false for new content.
    private func promote(_ kind: Kind, _ fingerprint: UInt64) -> Bool {
        guard let i = store.items.firstIndex(where: { $0.kind == kind && $0.fingerprint == fingerprint }) else { return false }
        if i > 0 {
            store.moveToTop(i)
            changed()
        }
        return true
    }

    /// Saves an entry in the background. Saves run in order, so the history keeps the order of the copies even when
    /// a big one takes a while.
    private func saveInBackground(_ kind: Kind, data: Data, write: @escaping @Sendable (UInt64, UInt64) -> Item) {
        let picksThen = picks, clearsThen = clears
        saving += 1
        io.async { [weak self] in
            let fingerprint = data.withUnsafeBytes { fingerprint($0) }
            let entry: UInt64 = DispatchQueue.main.sync {
                MainActor.assumeIsolated {
                    guard let self, !self.promote(kind, fingerprint) else { return 0 }
                    return self.store.newId()
                }
            }
            let item = entry == 0 ? Item() : autoreleasepool { write(entry, fingerprint) }
            DispatchQueue.main.async {
                MainActor.assumeIsolated {
                    guard let self else { return }
                    self.saving -= 1
                    guard item.id != 0 else { return }
                    if self.clears != clearsThen {  // the history was cleared meanwhile
                        self.store.forget(item.id)
                        return
                    }
                    // An entry picked from the list since this copy is newer, so it stays on top.
                    self.store.add(item, at: self.picks != picksThen ? 1 : 0)
                    self.changed()
                }
            }
        }
    }

    private func saveText(_ text: Data, rtf: Data?, html: Data?) {
        let paths = store.paths
        let write: @Sendable (UInt64, UInt64) -> Item = { entry, fingerprint in
            var item = Item(id: entry, kind: .text, flags: .text, fingerprint: fingerprint, bytes: UInt64(text.count))
            item.head = head(text)
            if !Crumb.write(paths.file(entry, "txt"), text) { item.id = 0 }
            if let rtf, !rtf.isEmpty, Crumb.write(paths.file(entry, "rtf"), rtf) { item.flags.insert(.rtf) }
            if let html, !html.isEmpty, Crumb.write(paths.file(entry, "html"), html) { item.flags.insert(.html) }
            return item
        }
        if busy || text.count + (rtf?.count ?? 0) + (html?.count ?? 0) > inlineBytes {
            saveInBackground(.text, data: text, write: write)
            return
        }
        // Small texts are saved at once, so they are already in the list if it opens right after the copy.
        let fingerprint = text.withUnsafeBytes { fingerprint($0) }
        if promote(.text, fingerprint) { return }
        let item = write(store.newId(), fingerprint)
        guard item.id != 0 else { return }
        store.add(item)
        changed()
    }

    private func saveImage(_ image: Data, type: NSPasteboard.PasteboardType, label: Data?) {
        let paths = store.paths
        saveInBackground(.image, data: image) { entry, fingerprint in
            var item = Item()
            let options = [kCGImageSourceShouldCache: false] as CFDictionary
            guard let source = CGImageSourceCreateWithData(image as CFData, options) else { return item }
            var (index, width, height, orientation) = largestImage(source)
            var stored: Data? = image
            var jpeg = type == jpegType
            if type == .tiff || index != 0 {
                // TIFF is usually uncompressed; PNG keeps the same pixels in a fraction of the space. A turned
                // picture is drawn upright first, as Crumb treats every PNG as upright.
                stored = orientation == 1 ? encodePNG(nil, source: source, index: index)
                                          : thumbnail(source, index, maxPixels: max(width, height)).flatMap { encodePNG($0) }
                jpeg = false
            }
            if (5...8).contains(orientation) { swap(&width, &height) }  // the size as the picture is shown
            guard let stored, width >= 1, height >= 1 else { return item }
            item = Item(id: entry, kind: .image, flags: jpeg ? [.image, .jpeg] : .image, fingerprint: fingerprint,
                        bytes: UInt64(image.count), width: UInt32(min(width, 1e9)), height: UInt32(min(height, 1e9)))
            if !Crumb.write(paths.imageFile(item), stored) { item.id = 0 }
            writeThumbnail(source, index, width: width, height: height, to: paths.file(entry, "thumb.png"))
            if item.id != 0, let label, !label.isEmpty, Crumb.write(paths.file(entry, "txt"), label) {
                item.flags.insert(.text)
                item.head = head(label)
            }
            return item
        }
    }

    private func saveFiles(_ list: [String]) {
        let data = Data(list.joined(separator: "\n").utf8)
        let paths = store.paths
        let write: @Sendable (UInt64, UInt64) -> Item = { entry, fingerprint in
            var item = Item(id: entry, kind: .files, fingerprint: fingerprint, bytes: UInt64(data.count))
            item.head = head(data)
            if !Crumb.write(paths.file(entry, "files"), data) { item.id = 0 }
            return item
        }
        if busy {
            saveInBackground(.files, data: data, write: write)
            return
        }
        let fingerprint = data.withUnsafeBytes { fingerprint($0) }
        if promote(.files, fingerprint) { return }
        let item = write(store.newId(), fingerprint)
        guard item.id != 0 else { return }
        store.add(item)
        changed()
    }

    func clearHistory() {
        clears += 1
        store.clear()
        changed()
    }

    /// Puts an entry back on the pasteboard and moves it to the top of the history.
    @discardableResult
    func copyItem(at index: Int) -> Bool {
        guard index < store.items.count else { return false }
        let item = store.items[index]
        let pasteboard = NSPasteboard.general
        var ok = false
        if item.kind == .files {
            let list = (try? String(contentsOfFile: store.file(item.id, "files"), encoding: .utf8)) ?? ""
            let urls = list.split(separator: "\n").map { URL(fileURLWithPath: String($0)) as NSURL }
            if !urls.isEmpty {
                pasteboard.clearContents()
                ok = pasteboard.writeObjects(urls)
            }
        } else {
            let entry = NSPasteboardItem()
            var any = false
            if item.flags.contains(.text), let data = mapped(store.file(item.id, "txt")) { any = entry.setData(data, forType: .string) }
            if item.flags.contains(.rtf), let data = mapped(store.file(item.id, "rtf")) { entry.setData(data, forType: .rtf) }
            if item.flags.contains(.html), let data = mapped(store.file(item.id, "html")) { entry.setData(data, forType: .html) }
            if item.flags.contains(.image), let data = mapped(store.imageFile(item)) {
                let jpeg = item.flags.contains(.jpeg)
                any = entry.setData(data, forType: jpeg ? jpegType : .png) || any
                entry.setDataProvider(ImageProvider(data), forTypes: jpeg ? [.png, .tiff] : [.tiff])
            }
            if any {
                pasteboard.clearContents()
                ok = pasteboard.writeObjects([entry])
            }
        }
        guard ok else {
            // Its files are gone (or unreadable): drop the entry rather than offer it again.
            store.remove(index)
            changed()
            return false
        }
        own = pasteboard.changeCount
        seen = own
        picks += 1
        store.moveToTop(index)
        return true
    }
}
